<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class AdminUserController extends Controller { public function index(){return response()->json(User::select('id','name','email','role','is_active','created_at','updated_at')->latest()->paginate(100));} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:190','email'=>'required|email|max:190|unique:users,email','password'=>'required|string|min:10','role'=>'required|in:admin,super_admin','is_active'=>'nullable|boolean']);$d['password']=Hash::make($d['password']);$u=User::create($d);return response()->json(['data'=>$u->only(['id','name','email','role','is_active'])],201);} public function update(Request $r,User $user){$d=$r->validate(['name'=>'sometimes|string|max:190','email'=>'sometimes|email|max:190|unique:users,email,'.$user->id,'password'=>'nullable|string|min:10','role'=>'sometimes|in:admin,super_admin','is_active'=>'sometimes|boolean']);if(!empty($d['password']))$d['password']=Hash::make($d['password']);else unset($d['password']);$user->update($d);return response()->json(['data'=>$user->only(['id','name','email','role','is_active'])]);} public function destroy(Request $r,User $user){abort_if($user->id===$r->user()->id,422,'You cannot delete your own active admin account.');$user->tokens()->delete();$user->delete();return response()->json(['message'=>'Admin user deleted.']);} }
